INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (22, '대파, 청파프리카, 홍파프리카, 황파프리카를 채 썬다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (22, '대구포에 밀가루를 묻혀 청파프리카, 홍파프리카, 황파프리카, 황금팽이버섯을 넣고 말아 미나리로 묶어 찐 후 소스를 뿌리고 썬 대파를 올려 완성한다.');
