INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (23, '배추를 소금물에 절이고 절인 배추를 찬물로 씻어 소금기를 뺀다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (23, '소금기를 뺀 배추에 채썬 자색고구마, 무, 쪽파, 부추, 사과, 배를 놓고 양념을 부은 후 3일 동안 숙성시켜 완성한다.');
