INSERT INTO recipe_ingredients (recipe_id, name, value, unit) VALUES (26, '올리브오일', 1, '작은술');
INSERT INTO recipe_ingredients (recipe_id, name, value, unit) VALUES (26, '올리브오일', 2, '큰술');
