INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (43, '양념장 재료를 모두 섞어 냉장고에서 하루 숙성시킨다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (43, '민어는 비늘을 긁고 지느러미, 내장을 제거하여 흐르는 물에 씻어 5cm 길이로 토막 낸다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (43, '소고기는 채 썰어 다진 마늘, 후추로 밑간한다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (43, '무는 나박 썰기, 애호박은 반달 썰기, 애느타리는 한입 크기로 찢고 고추와 대파는 어슷 썬다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (43, '냄비에 참기름을 두르고 소고기를 볶다가 물 1컵 반과 무를 넣고 양념장을 풀어 끓인다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (43, '무가 반 정도 익으면 민어와 채소를 넣고 한소끔 끓인 뒤 어슷 썬 대파와 생강즙을 넣어 살짝 끓이고 소금 간하고 쑥갓을 넣는다.');
