INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (95, '우렁은 3등분으로 자른 후 1의 재료와 함께 들기름에 볶고 달걀은 황백으로 나누어 지단을 부쳐 채 썬다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (95, '북어는 갈아 북어보푸라기를 만든다. 그릇에 밥을 담고 준비된 재료를 담고 베이비채소, 식용꽃, 북어보푸라기를 올려 완성한다.');
