INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (113, '겨자분말은 물에 섞은 후, 뜨거운 물 3g에 중탕하여 발효시킨 후 설탕과 식초를 넣어 겨자 소스를 만들고 당근, 무, 양파는 0.1×5cm로 채 썬다.');
