INSERT INTO recipe_ingredients (recipe_id, name, value, unit) VALUES (137, '오징어 몸통', 80, 'g');
INSERT INTO recipe_ingredients (recipe_id, name, value, unit) VALUES (137, '오이', 20, 'g');
