INSERT INTO recipe_seasonings (recipe_id, name, value, unit) VALUES (139, '소금', 0.5, 'g');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (139, '물 1컵 반에 홍합, 국멸치, 건다시마, 양파를 넣고 멸치다시마국물 1컵을 내고 다시마는 건져 채 썬다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (139, '감자는 껍질을 벗겨 찜통에 찐 후 으깬다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (139, '2의 재료에 쌀가루, 달걀노른자, 현미유, 소금을 넣고 반죽하여 구슬크기의 옹심이를 10개 정도 만든다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (139, '호박은 돌려깍기하여 2cm 가량으로 채 썰고 파, 홍고추, 청고추는 어슷썰기 한다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (139, '멸치다시마국물이 끓으면 옹심이를 넣고 익어서 떠오르면 홍합, 호박, 다진 파, 다진 마늘, 다시마를 넣고 국간장으로 간을 한다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (139, '홍고추와 청고추로 장식한다.');
