INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (142, '팬에 현미유를 두르고 반죽을 떠서 지름 8cm 가량의 크기로 동그랗게 부치면서 윗면에 홍고추로 장식한다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (142, '간장, 파, 식초, 통깨를 넣고 초간장을 만들어 물파래콩전과 곁들인다.');
