INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (163, '물 반컵을 넣고 국물이 자박하도록 푹 끓여낸다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (163, '완성된 머위나물을 식혀서 냉장고에 차게 보관하였다가 먹는다.');
