INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (168, '물 2/3컵에 국멸치와 건다시마를 넣고 끓여 국물을 내면서 이 열로 근대를 삼발이에 놓고 찐다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (168, '국물 우린 다시마를 잘게 썰어 쌀, 현미, 보리쌀과 함께 잡곡밥을 짓는다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (168, '잔멸치는 기름을 두르지 않고 팬에 살짝 볶아 다지고 견과류도 칼로 다진다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (168, '양파와 파를 다진다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (168, '고추장, 된장, 견과류, 양파, 다진 마늘, 매실액, 파, 멸치다시마국물을 섞어 멸치견과류쌈장을 만든다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (168, '근대위에 밥을 약 30g(1숟가락)정도 올리고 멸치견과류쌈장 5g 가량 넣어 근대잎으로 싼다.');
