INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (174, '국물낸 다슬기는 건져 달걀물과 함께 섞는다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (174, '부추는 1cm 가량의 크기로 썰고 대파는 어슷썰기 한다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (174, '국물이 끓어 오르면 호박잎과 부추, 파, 다진 마늘을 넣고 마지막으로 달걀물을 입힌 다슬기를 살포시 넣는다.');
