INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (175, '양배추는 씻어 잎을 넓게 뗀 후 7×12cm 가량의 크기로 자른다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (175, '자른 양배추는 김이 오른 찜통에 5분 정도 찐다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (175, '당근, 양파, 표고버섯은 곱게 다지고 두부는 으깨 면보에 짠다');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (175, '다진 돼지고기에 파, 다진 마늘, 참기름, 설탕, 소금, 후춧가루를 넣고 양념을 한 후 2의 재료와 섞는다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (175, '찐 양배추에 밀가루를 뿌리고 3의 재료를 놓고 돌돌 감아 찜통에 찐다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (175, '소스는 다진 양파와 마늘을 먼저 볶아 향을 낸 후 토마토케첩, 간장, 매실액을 넣어 만든다.');
