INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (177, '오징어는 내장을 제거하고 깨끗하고 씻어낸다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (177, '부추, 감자, 당근, 양파는 2cm 가량으로 곱게 채 썬다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (177, '부침가루와 미숫가루를 3 : 1의 비율로 섞는다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (177, '1, 2, 3에 물을 넣어 반죽하고 소금으로 간을 한다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (177, '팬에 현미유를 두르고 3의 반죽을 둥글게 떠 넣어 노릇노릇하게 지진다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (177, '그릇에 담아 완성한다.');
