INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (179, '고사리 삶는 중간에 취나물을 넣어 함께 데친다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (179, '고사리와 취나물은 잘게 썬다 .');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (179, '파프리카, 고사리, 취나물에 참기름, 마늘, 소금, 통깨를 넣고 양념을 한다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (179, '밥에 참기름, 통깨, 소금을 넣어 양념한 후 4의 재료를 섞어 주먹밥을 만든다.');
