INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (180, '썰어논 두부는 기름을 두르지 않고 팬에 노릇노릇 굽는다 .');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (180, '달래는 2cm 가량의 크기로 썬다 .');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (180, '배추김치는 물기를 적당히 짜고 2cm 가량으로 가늘게 채썬다 .');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (180, '홍피망은 2cm 가량으로 가늘게 채썰고 3, 4와 파, 마늘, 설탕, 참기름, 통깨, 고춧가루, 소금을 넣고 조물조물 무친다.');
INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (180, '두부위에 5의 김치달래무침을 곁들인다.');
